        await page.screenshot({ path: path.join(__dirname, "updated-mobile-solutions.png") });
        console.log("PASS five exact viewport sizes including 320px; no overflow or broken images");

        await page.goto("http://localhost:5188/product.html?product=diagnostics");
        const productHeight = await page.evaluate(() => document.documentElement.scrollHeight);
        assert.ok(productHeight <= 5654 * 0.85, `Product page did not compact sufficiently: ${productHeight}px`);
        assert.equal(await page.locator(".product-feature p:visible").count(), 10);
        assert.deepEqual(await page.locator(".brand-copy small").allTextContents(), brand);
